const G2_KEY='rules-city-gate2-v5';
const G2_BILLS={blue:{tag:'政府案',name:'《校園安全管理法部分條文修正草案》',by:'提案機關：行政院'},orange:{tag:'委員案',name:'《校園安全管理法第十二條、第十五條及第十八條條文修正草案》',by:'提案人：陳○○等｜連署：17人'}};
const G2_DOCS={agenda:{title:'議事日程審定紀錄',body:'兩份法律案已排入院會議程。'},direct:{title:'逕付二讀紀錄',body:'出席委員提議，經20人以上連署或附議，並由院會表決通過。'},report:{title:'委員會審查報告',body:'審查結果：審查完成。部分條文仍有爭議，本案決議交付黨團協商。'},negotiation:{title:'黨團協商結論',body:'本案部分條文依協商內容修正；代表簽署確認結論。'},second:{title:'第二讀會程序紀錄',body:'本案依序完成廣泛討論、逐條討論與條文議決。'},third:{title:'第三讀會議決紀錄',body:'本案完成第三讀會，並經全案表決通過。'},promulgation:{title:'公布紀錄',body:'立法院咨請總統公布，公布日期為10月12日。'}};
const G2_INIT=()=>({stage:'intro',intro:false,viewed:[],agenda:[],agendaSelected:null,branch:{},choiceBill:null,sign:18,signers:[],review:[],reviewSelected:null,folder:[],negSlots:[null,null,null],negSelected:null,negConfirmed:false,negStamped:false,order:[null,null,null],orderSelected:null,orderPool:[],third:0,falseFinish:false,promulgated:false,effective:false,verify:[null,null,null,null],verifySelected:null,verifyPool:[],done:false});
let g2=G2_INIT();const g2App=document.querySelector('#app');
function g2Save(){localStorage.setItem(G2_KEY,JSON.stringify(g2))}
function g2Load(){try{let x=JSON.parse(localStorage.getItem(G2_KEY));if(x&&x.stage){g2={...G2_INIT(),...x};if(!Array.isArray(g2.signers))g2.signers=[];g2.sign=18+g2.signers.length;if(!Array.isArray(g2.verify)||g2.verify.length!==4)g2.verify=[null,null,null,null]}}catch(e){}}
function g2Esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function g2AddDoc(id){if(!g2.folder.includes(id))g2.folder.push(id);g2Save()}
function g2Hud(){return `<header class="g2-hud"><div><b>貳｜尚未完成的法案</b><small>立法程序紀錄</small></div><button class="g2-folder" data-action="folder">▰<span>文件夾</span></button></header>`}
function g2Scene(place,content){g2App.innerHTML=`<section class="g2-game g2-${place}">${g2Hud()}<div class="g2-place-name">${place==='committee'?'委員會會議室':place==='negotiation'?'黨團協商會議室':'立法院議場'}</div><main class="g2-stage">${content}</main><p class="g2-message" id="g2-message"></p></section>`;if(place==='negotiation'){let b=document.querySelector('.g2-clipboard');if(b)b.style.backgroundImage="linear-gradient(#5a3e2c,#8a684c),var(--g2-evidence-board)"}g2Bind()}
function g2Message(text){let p=document.querySelector('#g2-message');if(p)p.textContent=text}
function g2Modal(html){let e=document.createElement('section');e.className='g2-modal';e.innerHTML=`<div class="g2-modal-paper"><button class="g2-close" data-action="close">×</button>${html}</div>`;g2App.append(e);g2Bind()}
function g2Folder(){document.querySelector('.g2-modal')?.remove();g2Modal(`<h2>文件夾</h2><p class="g2-folder-intro">這些文件是你修復程序紀錄時留下的證據，可隨時點開回看。</p>${g2.folder.length?g2.folder.map(id=>`<button class="g2-folder-row" data-action="doc" data-docid="${id}">${g2Esc(G2_DOCS[id].title)}</button>`).join(''):'<p>目前還沒有程序文件。</p>'}<p class="g2-folder-actions"><button class="g2-replay-link" data-action="replay-ask">重玩第二關</button></p>`) }
function g2ReplayAsk(){document.querySelector('.g2-modal')?.remove();g2Modal(`<h2>確定要重新挑戰本關嗎？</h2><p class="g2-folder-intro">本次挑戰的程序進度與文件蒐集紀錄將重設；其他關卡不受影響。</p><button class="g2-replay-confirm" data-action="replay-confirm">重新挑戰本關</button><button class="g2-replay-cancel" data-action="folder">取消</button>`)}
function g2Replay(){localStorage.removeItem('rules-city-gate2-v4');localStorage.removeItem(G2_KEY);g2=G2_INIT();g2Save();g2Render()}
function g2ShowDoc(id){let d=G2_DOCS[id];g2Modal(`<article class="g2-document-view"><em>程序文件</em><h2>${g2Esc(d.title)}</h2><p>${g2Esc(d.body)}</p></article>`)}
function g2Start(){g2Load();if(g2.done&&g2.stage!=='complete'){g2.stage='complete';g2Save()}g2Render()}
function g2CompletedOptions(){g2Modal(`<h2>第二關已完成</h2><p class="g2-folder-intro">這份立法程序紀錄已修復完成。</p><button class="g2-replay-confirm" data-action="notebook">查看公民筆記</button><button class="g2-replay-cancel" data-action="replay-ask">重新挑戰本關</button><button class="g2-replay-cancel" data-action="return-city">返回規則之城</button>`)}
function g2Render(){({intro,agenda,first,branch,direct,directexit,committeeintro,committee,committeecomplete,committeeexit,negotiation,second,third,falsefinish,promulgation,effective,verify,verifycomplete,complete}[g2.stage]||intro)()}
function intro(){g2Scene('chamber panorama',`<div class="g2-explore-pan" id="g2-explore-pan"><div class="g2-explore-world"><div class="g2-intro-docs ${g2.intro?'show':''}"><button class="g2-scene-file blue" data-action="viewbill" data-bill="blue"><small>政府案</small>查看行政院案</button><button class="g2-scene-file orange" data-action="viewbill" data-bill="orange"><small>委員案</small>查看委員案</button>${g2.viewed.length===2?'<button class="g2-begin-procedure" data-action="to-agenda">前往議事程序桌</button>':''}</div></div></div><div class="g2-arrival"><b>貳｜尚未完成的法案</b><span>兩份尚未完成的立法紀錄，散落在這裡。</span></div><div class="g2-intro-dialogue ${g2.intro?'hidden':''}"><p>本屆立法委員任期即將屆滿。</p><p>但還有兩份修法紀錄，沒有走完。</p><p>在時間結束以前，把它們送回正確的程序。</p><button data-action="intro">開始追蹤</button></div><div class="g2-swipe-cue ${g2.intro?'show':''}">左右滑動查看議場</div>`) }
function g2ViewBill(id){if(!g2.viewed.includes(id)){g2.viewed.push(id);g2Save()}let b=G2_BILLS[id];g2Modal(`<article class="g2-document-view bill-view ${id}"><em>${b.tag==='政府案'?'法律案':'委員提案'}</em><h2>${b.name}</h2><p>${b.by}</p><div class="g2-lines"></div><small>查看後，文件仍會放回議事桌。</small></article>`)}
function billButton(id,action,selected=false){let b=G2_BILLS[id];return `<button class="g2-bill ${id} ${selected?'picked':''}" data-action="${action}" data-bill="${id}"><small>${b.tag}</small><b>${b.name}</b><span>${b.by}</span></button>`}
function agenda(){let left=Object.keys(G2_BILLS).filter(id=>!g2.agenda.includes(id)),chosen=g2.agendaSelected;g2Scene('chamber',`<p class="g2-prompt">${chosen?'這份法律案提出後，下一步應進入哪個程序？':'先點選一份法律案，看看下一步該走哪個程序。'}</p><div class="g2-agenda-table"><div class="g2-agenda-book"><em>議事日程</em><b>程序委員會紀錄</b><small>${g2.agenda.length?'已收入的法律案正等待排程':'兩份法律案正等待排入院會議程'}</small></div><div class="g2-trays g2-choice-targets ${chosen?'ready':''}"><button class="g2-tray procedure" data-action="agenda-choice" data-value="procedure"><b>程序委員會</b><small>議事日程</small></button><button class="g2-tray" data-action="agenda-choice" data-value="committee"><b>委員會審查</b><small>審查法案</small></button><button class="g2-tray" data-action="agenda-choice" data-value="second"><b>第二讀會</b><small>院會程序</small></button></div></div><div class="g2-bill-pair">${left.map(id=>billButton(id,'agenda-bill',chosen===id)).join('')}</div>`) }
function first(){g2Scene('chamber',`<article class="g2-record"><em>第一讀會</em><h2>主席台前的程序紀錄</h2><p>選擇此刻應進行的動作。</p></article><div class="g2-slip-row">${['朗讀議案標題','逐條討論','全案表決'].map(x=>`<button data-action="first" data-value="${x}">${x}</button>`).join('')}</div>`) }
function branch(){let picked=g2.choiceBill,remaining=Object.keys(G2_BILLS).filter(id=>!g2.branch[id]),record=picked==='blue'?'本案一讀後，決議交付委員會審查。':picked==='orange'?'本案一讀後，有委員提議逕付二讀。':'';let prompt=picked?'依照院會紀錄，這份法案下一步該去哪裡？':remaining.length===1?'還有另一份法案，點選它查看院會紀錄。':'一讀完成，兩份法案將走向不同的程序。先點選一份法案。';g2Scene('chamber',`<p class="g2-prompt g2-branch-prompt">${prompt}</p><div class="g2-bill-pair g2-branch-bills">${remaining.map(id=>billButton(id,'branch-bill',picked===id)).join('')}</div>${record?`<article class="g2-branch-record"><em>院會紀錄</em><p>「${record}」</p></article>`:''}<div class="g2-tray-pair g2-branch-options ${picked?'ready':''}"><button class="g2-tray" data-action="branch-choice" data-value="committee"><b>委員會審查</b></button><button class="g2-tray" data-action="branch-choice" data-value="direct"><b>逕付二讀</b></button></div>`) }
function direct(){let names=['林委員','許委員','周委員','方委員','吳委員'];g2Scene('chamber',`<article class="g2-record signature"><em>逕付二讀程序紀錄</em><p>提議：已完成</p><p>連署／附議：目前 <b>${g2.sign} 人</b></p></article><button class="g2-sign-book"><b>連署名冊</b><small>點選委員加入連署／附議</small></button><div class="g2-name-row">${names.map((n,i)=>`<button class="${g2.signers.includes(i)?'selected':''}" data-action="toggle-sign" data-value="${i}">${n}${g2.signers.includes(i)?' ✓':''}</button>`).join('')}</div><button class="g2-vote ${g2.sign<20?'locked':''}" data-action="vote">送交院會表決</button>`) }
function directexit(){g2Scene('chamber',`<article class="g2-record compact"><em>逕付二讀</em><p>院會表決通過，委員案逕付二讀。</p><small>這份案子的程序還沒有結束。</small></article><p class="g2-prompt">下一步應送往哪裡？</p><div class="g2-tray-pair"><button class="g2-tray" data-action="directexit-choice" data-value="second"><b>第二讀會</b></button><button class="g2-tray" data-action="directexit-choice" data-value="negotiation"><b>黨團協商</b></button></div>`) }
function committeeintro(){g2Scene('committee',`<article class="g2-record compact"><p>另一邊，行政院案也正在進行……</p><p>委員案已完成逕付二讀程序，進入黨團協商。</p><p>現在回到行政院案：它已交付委員會審查。</p><button class="g2-vote" data-action="to-committee">前往委員會</button></article>`) }
const COMMITTEE_FILES={amend:{title:'修正意見',body:'針對審查中的條文提出修正建議。'},reserve:{title:'保留意見',body:'記錄委員會審查時保留的不同意見。'},review:{title:'審查資料',body:'委員會審查所使用的基礎資料。'},negotiation:{title:'黨團協商結論',body:'協商後才形成的結論文件。'},second:{title:'第二讀會逐條討論紀錄',body:'第二讀會才會形成的程序紀錄。'}};
function committee(){let remaining=Object.keys(COMMITTEE_FILES).filter(id=>!g2.review.includes(id)),selected=g2.reviewSelected,d=selected&&COMMITTEE_FILES[selected];g2Scene('committee',`<p class="g2-prompt">桌上混著不同程序留下的文件。先點選文件閱讀，再收入屬於「委員會審查」階段的資料。</p><div class="g2-review-table g2-review-sort"><button class="g2-review-folder ${selected?'ready':''}" data-action="review-store"><b>委員會審查資料夾</b><small>${selected?'收入審查資料夾':'點選文件後，收入資料夾'}</small><div class="g2-folder-tabs">${g2.review.map(id=>`<i>${COMMITTEE_FILES[id].title}</i>`).join('')}</div></button><div class="g2-review-scatter">${remaining.map(id=>`<button class="g2-committee-paper ${id} ${selected===id?'picked':''}" data-action="review-select" data-value="${id}"><b>${COMMITTEE_FILES[id].title}</b><small>${COMMITTEE_FILES[id].body}</small></button>`).join('')}</div></div>${d?`<article class="g2-review-preview"><b>${d.title}</b><p>${d.body}</p></article>`:''}`) }
function committeecomplete(){g2Scene('committee',`<p class="g2-prompt">資料夾已整理完成，正在彙整審查意見。</p><div class="g2-review-table g2-review-complete"><div class="g2-review-folder closed"><b>委員會審查資料夾</b><small>審查資料已歸檔</small></div><article class="g2-generated-report"><em>委員會審查報告</em><h2>《委員會審查報告》</h2><p>審查結果：審查完成</p><p>部分條文仍有爭議</p><p>本案決議交付黨團協商</p><i>已收入程序文件夾</i><button class="g2-vote" data-action="committee-report-ready">查看程序去向</button></article></div>`) }
function committeeexit(){g2Scene('committee',`<article class="g2-report"><em>委員會審查報告</em><p>委員會已完成審查，但部分條文仍有爭議。</p><p>依本案審查決議，接下來需要進入黨團協商。</p></article><div class="g2-tray-pair"><button class="g2-tray" data-action="committee-choice" data-value="second"><b>第二讀會</b></button><button class="g2-tray" data-action="committee-choice" data-value="negotiation"><b>黨團協商</b></button></div>`) }
const NEG={head:{title:'協商案由',body:'本案針對爭議條文進行協商'},body:{title:'協商紀錄',body:'各黨團就爭議條文提出意見'},sign:{title:'協商結論與簽署',body:'記載協商結果，並由各黨團代表簽署'},report:{title:'委員會審查報告',body:'審查完成・前一階段文件'},second:{title:'第二讀會逐條討論紀錄',body:'尚未進入第二讀會'}};
function negPaper(id,selected=false){let d=NEG[id];return `<button class="g2-paper neg ${id} ${selected?'picked':''}" data-action="neg-select" data-value="${id}"><b>${d.title}</b><small>${d.body}</small></button>`}
function negotiation(){let slots=g2.negSlots,available=Object.keys(NEG).filter(id=>!slots.includes(id)),full=slots.every(Boolean),ready=full&&g2.negConfirmed&&!g2.negStamped;g2Scene('negotiation',`<p class="g2-prompt">先點選桌上的文件，再點擊文件板中的位置，修復一份完整的協商結論。</p><div class="g2-neg-desk"><div class="g2-clipboard"><div class="g2-clip-title">黨團協商結論</div>${[0,1,2].map(i=>`<button class="g2-neg-slot ${slots[i]?'filled':''}" style="top:${[17,42,67][i]}%;height:22%" data-action="neg-slot" data-value="${i}"><i>${['①','②','③'][i]}</i>${slots[i]?`<b>${NEG[slots[i]].title}</b>`:'<span>放入文件</span>'}</button>`).join('')}<div class="g2-stamp-area" style="left:12%;right:12%;bottom:2%;height:8%;display:grid;place-items:center">${ready?'文件已完成，點擊印章確認。':'蓋章區'}</div></div><div class="g2-neg-scatter">${available.map(id=>negPaper(id,g2.negSelected===id)).join('')}</div><button class="g2-confirm ${full?'ready':''}" data-action="confirm-neg">確認文件</button><button class="g2-stamp ${ready?'ready':''} ${g2.negStamped?'stamped':''}" data-action="neg-stamp" ${ready?'':'disabled'}>黨團協商<br>完成</button></div>`) }
const ORDER=['廣泛討論','逐條討論','條文議決'];
function orderPaper(x,selected=false){return `<button class="g2-paper order ${selected?'picked':''}" data-action="order-select" data-value="${x}"><b>${x}</b><small>第二讀會程序</small></button>`}
function second(){let pool=(g2.orderPool.length?g2.orderPool:['條文議決','廣泛討論','逐條討論']).filter(x=>!g2.order.includes(x)),full=g2.order.every(Boolean);g2Scene('chamber',`<p class="g2-prompt">先點選一張程序紙條，再點擊紀錄板的位置完成排序。</p><div class="g2-order-board"><b>第二讀會程序紀錄</b><div>${[0,1,2].map(i=>`<button class="g2-order-slot ${g2.order[i]?'filled':''}" data-action="order-slot" data-value="${i}"><i>${['①','②','③'][i]}</i>${g2.order[i]?`<b>${g2.order[i]}</b>`:'<span>放入紙條</span>'}</button>`).join('')}</div><button class="g2-confirm ${full?'ready':''}" data-action="confirm-order">確認程序</button><button class="g2-order-reset" data-action="reset-order">↺ 重新排列</button></div><div class="g2-order-source">${pool.map(x=>orderPaper(x,g2.orderSelected===x)).join('')}</div>`) }
function third(){let p=g2.third;let big=`<article class="g2-third-page"><em>第三讀會文字修正</em><p>原文：「違反者處新臺幣 <del>一萬元</del> 罰鍰。」</p><p>修正：「違反者處新臺幣 <strong>十萬元</strong> 罰鍰。」</p><div><button class="g2-review-stamp" data-action="third" data-value="accept-big">接受修正</button><button class="g2-review-stamp" data-action="third" data-value="reject-big">退回</button></div></article>`;let small=`<article class="g2-third-page"><em>第三讀會文字修正</em><p>原文：「主管機關應<del>予以</del>通知。」</p><p>修正：「主管機關應通知。」</p><small>義務內容未改變，僅精簡文字。</small><div><button class="g2-review-stamp" data-action="third" data-value="accept-small">接受文字修正</button><button class="g2-review-stamp" data-action="third" data-value="reject-small">退回</button></div></article>`;g2Scene('chamber dark',`<div class="g2-desk-lamp"></div>${p===0?big:p===1?small:`<article class="g2-third-page passed"><div class="g2-big-stamp">文字修正</div><p>修正已確認，準備進行全案表決。</p><button class="g2-vote" data-action="third-vote">全案表決</button></article>`}`)}
function falsefinish(){g2Scene('chamber',`<article class="g2-false-finish"><div class="g2-big-stamp">三讀通過</div><p>議場裡響起主席槌聲，文件似乎終於完成了。</p><button data-action="false-finish">確認程序紀錄</button></article>`) }
function promulgation(){g2Scene('chamber',`<article class="g2-envelope"><em>三讀通過法律案</em><b>立法院咨請公布</b></article><p class="g2-prompt">公文應送往哪一個機關？</p><div class="g2-recipients"><button class="g2-tray" data-action="promulgation-choice" data-value="executive">行政院</button><button class="g2-tray" data-action="promulgation-choice" data-value="president">總統府</button><button class="g2-tray" data-action="promulgation-choice" data-value="judicial">司法院</button></div>`) }
function effective(){g2Scene('chamber',`<article class="g2-public-record"><em>公布紀錄</em><b>公布日期：10月12日</b><small>本法規定自公布日施行。</small></article><p class="g2-prompt">請選擇生效日。</p><div class="g2-calendar">${['10/12','10/13','10/14','10/15'].map((d,i)=>`<button data-action="effective-choice" data-value="${i}"><b>${d}</b></button>`).join('')}</div><div class="g2-effective-stamp">生效</div>`) }
function evidencePaper(id,selected=false){return `<button class="g2-paper evidence ${selected?'picked':''}" data-action="verify-select" data-value="${id}"><b>${G2_DOCS[id].title}</b><small>${G2_DOCS[id].body}</small></button>`}
function verify(){let pool=(g2.verifyPool.length?g2.verifyPool:['third','second','report','negotiation']).filter(id=>!g2.verify.includes(id)),full=g2.verify.every(Boolean);g2Scene('chamber verify-stage',`<p class="g2-prompt">利用一路蒐集到的程序文件，還原本案實際走過的順序。</p><article class="g2-verify-sheet"><h2>程序證據冊・核對頁</h2><p class="g2-verify-note">依本案實際經過的程序排列文件。</p><div class="g2-verify-agenda"><span>已完成紀錄</span><b>議事日程審定紀錄 <i>✓</i></b></div><div class="g2-verify-slots">${[0,1,2,3].map(i=>`<button class="g2-verify-row ${g2.verify[i]?'filled':''}" data-action="verify-slot" data-value="${i}"><span>${['①','②','③','④'][i]}</span>${g2.verify[i]?`<b>${G2_DOCS[g2.verify[i]].title}</b>`:'<b>＿＿＿＿＿＿＿＿</b>'}</button>`).join('')}</div><div class="g2-evidence-source g2-verify-source">${pool.map(id=>evidencePaper(id)).join('')}</div><button class="g2-confirm ${full?'ready':''}" data-action="confirm-verify">核對程序</button></article>`) }
function verifycomplete(){g2Scene('chamber verify-stage',`<article class="g2-verify-sheet g2-verified"><h2>程序核對完成 ✓</h2><p>這份法律案已經完成第三讀會，<br>接下來可以進入公布程序。</p><b class="g2-route-label">政府案程序紀錄</b><p>委員會審查<br>↓<br>黨團協商<br>↓<br>第二讀會<br>↓<br>第三讀會</p><aside class="g2-civic-reminder"><b>📌 公民小提醒</b><p>這是本次政府案實際經過的立法程序。<br><br>法律案在第一讀會後，可能交付委員會審查，也可能逕付二讀。<br><br>委員會審查後，不一定需要黨團協商；但逕付二讀的法律案，應交付黨團協商。<br><br>不同法律案的程序不一定完全相同。</p></aside><button class="g2-vote" data-action="to-promulgation">送出公布公文</button></article>`) }
function complete(){g2Scene('chamber complete-stage',`<article class="g2-complete"><div class="g2-big-stamp">程序完成</div><h2>尚未完成的法案</h2><div class="g2-final-flow"><p>提案<br>↓<br>程序委員會<br>↓<br>第一讀會</p><div><b>兩條程序路線</b><p>路線A：委員會審查<br>→ 視本案決議進入黨團協商</p><p>路線B：逕付二讀<br>→ 黨團協商（必經）</p></div><p>↓<br>第二讀會<br>↓<br>第三讀會<br>↓<br>立法院咨請總統公布<br>↓<br>總統公布<br>↓<br>法律生效</p></div><div class="g2-complete-actions"><button class="g2-vote" data-action="notebook">查看公民筆記</button><button class="g2-vote" data-action="return-city">返回規則之城</button><button class="g2-vote" data-action="reset">重新挑戰本關</button></div></article>`) }
function notebook(){let note=window.LEVEL2_CONTENT?.notebook||{},sections=note.sections||[],line=p=>`<p class="${p.endsWith('：')?'g2-notebook-label':p.startsWith('【')?'g2-notebook-route':''}">${g2Esc(p).replaceAll(' ↓ ','<br>↓<br>')}</p>`;document.querySelector('.g2-modal')?.remove();g2Scene('chamber notebook-stage',`<article class="g2-notebook"><div class="g2-big-stamp">程序完成</div><h1>${g2Esc(note.title||'公民筆記02｜立法程序')}</h1>${sections.map(([h,ps])=>`<section><h2>${g2Esc(h)}</h2>${ps.map(line).join('')}</section>`).join('')}<div class="g2-notebook-actions"><button data-action="return-city">返回規則之城</button><button data-action="reset">重新挑戰本關</button></div></article>`) }
function g2Advance(stage,msg){g2.stage=stage;g2Save();g2Render();if(msg)g2Message(msg)}
function setSlot(key,selectedKey,index){let value=g2[selectedKey];if(!value){let existing=g2[key][index];if(existing){g2[key][index]=null;g2[selectedKey]=existing;g2Save();g2Render()}return}let old=g2[key][index];g2[key][index]=value;g2[selectedKey]=old||null;g2Save();g2Render()}
function g2Action(a,el){
if(a==='close'){document.querySelector('.g2-modal')?.remove();if(g2.stage==='intro')g2Render();return}if(a==='folder')return g2Folder();if(a==='doc')return g2ShowDoc(el.dataset.docid);if(a==='replay-ask')return g2ReplayAsk();if(a==='replay-confirm')return g2Replay();if(a==='return-city')return window.location.assign('../index.html');if(a==='intro'){g2.intro=true;g2Save();return g2Render()}if(a==='viewbill')return g2ViewBill(el.dataset.bill);if(a==='to-agenda')return g2Advance('agenda');
if(a==='agenda-bill'){let id=el.dataset.bill;g2.agendaSelected=g2.agendaSelected===id?null:id;g2Save();return g2Render()}if(a==='agenda-choice'){let id=g2.agendaSelected,v=el.dataset.value;if(!id)return g2Message('先點選一份法律案。');if(v!=='procedure')return g2Message(v==='committee'?'尚未經院會交付，不能直接進入委員會審查。':'程序尚未走到第二讀會。');g2.agenda.push(id);g2.agendaSelected=null;if(g2.agenda.length===2){g2AddDoc('agenda');return g2Advance('first','議事日程審定。兩案已排入院會議程。')}g2Save();return g2Render()}
if(a==='first'){if(el.dataset.value!=='朗讀議案標題')return g2Message('尚未進入該程序。');return g2Advance('branch','一讀完成。兩案將走向不同的程序。')}if(a==='branch-bill'){g2.choiceBill=g2.choiceBill===el.dataset.bill?null:el.dataset.bill;g2Save();return g2Render()}if(a==='branch-choice'){let bill=g2.choiceBill,target=el.dataset.value;if(!bill)return g2Message('先點選一份法案。');let ok=(bill==='blue'&&target==='committee')||(bill==='orange'&&target==='direct');if(!ok)return g2Message('這份法案的程序紀錄不是這樣。再想想一讀後的去向。');g2.branch[bill]=target;g2.choiceBill=null;if(g2.branch.blue&&g2.branch.orange)return g2Advance('direct','兩案分流。先追蹤逕付二讀的紀錄。');g2Save();return g2Render()}
if(a==='toggle-sign'){let i=+el.dataset.value,at=g2.signers.indexOf(i);if(at>-1)g2.signers.splice(at,1);else g2.signers.push(i);g2.sign=18+g2.signers.length;g2Save();return g2Render()}if(a==='vote'){if(g2.sign<20)return g2Message('連署／附議人數似乎還不足，程序還不能往下進行。');g2AddDoc('direct');return g2Advance('directexit','逕付二讀：出席委員提議 → 20人以上連署或附議 → 院會表決通過。')}
if(a==='directexit-choice'){if(el.dataset.value!=='negotiation')return g2Message('逕付二讀的法律案，依法應交付黨團協商。');g2AddDoc('direct');return g2Advance('committeeintro')}if(a==='to-committee')return g2Advance('committee');
if(a==='review-select'){let id=el.dataset.value;g2.reviewSelected=g2.reviewSelected===id?null:id;g2Save();return g2Render()}if(a==='review-store'){let id=g2.reviewSelected;if(!id)return g2Message('先點選一份文件閱讀。');if(id==='negotiation')return g2Message('這份文件屬於後面的黨團協商階段。');if(id==='second')return g2Message('程序還沒進入第二讀會，現在不會有這份紀錄。');g2.review.push(id);g2.reviewSelected=null;if(g2.review.length===3){g2AddDoc('report');return g2Advance('committeecomplete','審查資料已整理完成。')}g2Save();return g2Render()}
if(a==='committee-report-ready')return g2Advance('committeeexit');if(a==='committee-choice'){if(el.dataset.value!=='negotiation')return g2Message('本案的審查報告還有一項程序決議，再查看一次。');return g2Advance('negotiation','兩案在黨團協商會合。')}
if(a==='neg-select'){let id=el.dataset.value;g2.negSelected=g2.negSelected===id?null:id;g2Save();return g2Render()}if(a==='neg-slot')return setSlot('negSlots','negSelected',+el.dataset.value);if(a==='confirm-neg'){if(!g2.negSlots.every(Boolean))return;let ok=g2.negSlots.join('|')==='head|body|sign';if(!ok)return g2Message('文件的位置似乎不對。請重新檢查後再確認。');g2.negConfirmed=true;g2Save();return g2Render()}if(a==='neg-stamp'){if(!g2.negConfirmed)return;g2.negStamped=true;g2AddDoc('negotiation');return g2Advance('second','黨團協商完成。')}
if(a==='order-select'){let x=el.dataset.value;g2.orderSelected=g2.orderSelected===x?null:x;g2Save();return g2Render()}if(a==='order-slot')return setSlot('order','orderSelected',+el.dataset.value);if(a==='reset-order'){g2.order=[null,null,null];g2.orderSelected=null;g2.orderPool=ORDER.slice().sort(()=>Math.random()-.5);g2Save();return g2Render()}if(a==='confirm-order'){if(!g2.order.every(Boolean))return;let ok=g2.order.join('|')===ORDER.join('|');if(!ok)return g2Message('程序順序似乎不對，再檢查一次。');g2AddDoc('second');return g2Advance('third','第二讀會完成。')}
if(a==='third'){let v=el.dataset.value;if(v==='accept-big')return g2Message('這不只是文字修正。');if(v==='reject-big'){g2.third=1;g2Save();return g2Render()}if(v==='accept-small'){g2.third=2;g2Save();return g2Render()}return g2Message('請再比對修正內容。')}if(a==='third-vote'){g2AddDoc('third');return g2Advance('falsefinish','三讀通過。')}
if(a==='false-finish'){g2.falseFinish=true;g2.verify=[null,null,null,null];g2.verifySelected=null;g2.verifyPool=['third','second','report','negotiation'].sort(()=>Math.random()-.5);g2Save();return g2Advance('verify','三讀通過後，程序仍需依據紀錄核對。')}
if(a==='verify-select'){let id=el.dataset.value,slot=g2.verify.indexOf(null);if(slot<0)return;g2.verify[slot]=id;g2.verifySelected=null;g2Save();return g2Render()}if(a==='verify-slot'){let slot=+el.dataset.value;if(!g2.verify[slot])return;g2.verify[slot]=null;g2.verifySelected=null;g2Save();return g2Render()}if(a==='reset-verify'){g2.verify=[null,null,null,null];g2.verifySelected=null;g2.verifyPool=['third','second','report','negotiation'].sort(()=>Math.random()-.5);g2Save();return g2Render()}if(a==='confirm-verify'){if(!g2.verify.every(Boolean))return;let ok=g2.verify.join('|')==='report|negotiation|second|third';if(!ok)return g2Message('程序順序似乎不太對，再檢查一次吧！');g2Save();return g2Advance('verifycomplete')}
if(a==='to-promulgation')return g2Advance('promulgation');if(a==='promulgation-choice'){if(el.dataset.value!=='president')return g2Message('這不是公布法律的機關。');g2.promulgated=true;g2AddDoc('promulgation');return g2Advance('effective','立法院咨請總統公布。公布日期：10月12日。')}if(a==='effective-choice'){if(el.dataset.value!=='2')return g2Message('日期似乎不對，再算一次。');g2.effective=true;g2.done=true;g2Save();return g2Advance('complete','法律生效。程序紀錄完成。')}if(a==='notebook')return notebook();if(a==='reset')return g2ReplayAsk()}
function g2Bind(){document.querySelectorAll('[data-action]').forEach(e=>{if(e.dataset.g2bound)return;e.dataset.g2bound='1';e.addEventListener('click',()=>g2Action(e.dataset.action,e))});let pan=document.querySelector('#g2-explore-pan');if(!pan||pan.dataset.g2bound)return;pan.dataset.g2bound='1';let down=false,startX=0,startLeft=0;pan.scrollLeft=(pan.scrollWidth-pan.clientWidth)/2;pan.addEventListener('pointerdown',ev=>{if(ev.target.closest('.g2-scene-file,.g2-begin-procedure,.g2-hud'))return;down=true;startX=ev.clientX;startLeft=pan.scrollLeft;pan.setPointerCapture?.(ev.pointerId);pan.classList.add('dragging')});pan.addEventListener('pointermove',ev=>{if(!down)return;pan.scrollLeft=startLeft-(ev.clientX-startX);ev.preventDefault()});['pointerup','pointercancel'].forEach(t=>pan.addEventListener(t,()=>{down=false;pan.classList.remove('dragging')}))}
g2App.style.maxWidth='none';g2App.style.width='100vw';g2App.style.margin='0';document.documentElement.style.setProperty('--g2-evidence-board',"url('assets/overlays/evidence-clipboard-v1.png')");g2Start();
